<?php
/** Material Design 3: principles and Material You, colour roles and dynamic colour, components, layout, elevation and motion. */

return [
    'id' => 'material', 'family' => 'material', 'after' => 'ui-base', 'categories' => ['design', 'mobile', 'frontend'],
    'title' => L('Material Design', 'Material Design'), 'short' => L('Material', 'Material'), 'level' => L('Intermedio', 'Intermediate'),
    'desc' => L('Il design system di Google: Material 3 e Material You, ruoli di colore e colore dinamico, tipografia e forme, componenti, layout adattivi, elevazione e movimento.', 'Google’s design system: Material 3 and Material You, colour roles and dynamic colour, typography and shapes, components, adaptive layouts, elevation and motion.'),
    'lessons' => [
        lesson('principles', L('Principi e Material You', 'Principles and Material You'), [
            P('**Material Design** è il design system di Google, nato nel 2014 con la metafora del **materiale**: superfici come fogli di carta con profondità, luce e ombre. La versione attuale, **Material 3** (M3), introduce **Material You**: interfacce più personali, colori presi dallo sfondo del telefono, forme più morbide e arrotondate, componenti più accessibili.', '**Material Design** is Google’s design system, born in 2014 with the **material** metaphor: surfaces like sheets of paper with depth, light and shadow. The current version, **Material 3** (M3), introduces **Material You**: more personal interfaces, colours taken from the phone’s wallpaper, softer and rounder shapes, more accessible components.'),
            P('Material è usato in Android, nelle app Google e sul web (con librerie come **Material Web**, **MUI** per React, **Angular Material**, **Jetpack Compose Material 3** e **Flutter**). Le linee guida su m3.material.io coprono fondamenti (accessibilità, layout, interazione), **stili** (colore, tipografia, forme, elevazione, icone, movimento) e **componenti**.', 'Material is used in Android, Google apps and on the web (with libraries such as **Material Web**, **MUI** for React, **Angular Material**, **Jetpack Compose Material 3** and **Flutter**). The guidelines on m3.material.io cover foundations (accessibility, layout, interaction), **styles** (colour, typography, shape, elevation, icons, motion) and **components**.'),
        ], [
            Q('p1', L('Qual era la metafora originale di Material?', 'What was Material’s original metaphor?'), [L('Superfici come fogli di carta con profondità', 'Surfaces like sheets of paper with depth'), L('Vetro trasparente', 'Transparent glass'), L('Mattoni di Lego', 'Lego bricks'), L('Pixel art', 'Pixel art')], 0, L('Luce, ombra, profondità.', 'Light, shadow, depth.')),
            Q('p2', L('Che cosa porta Material You?', 'What does Material You bring?'), [L('Colori personali presi dallo sfondo', 'Personal colours taken from the wallpaper'), L('Solo il tema scuro', 'Only dark mode'), L('Icone 3D obbligatorie', 'Mandatory 3D icons'), L('Font a mano', 'Handwritten fonts')], 0, L('Interfacce personali.', 'Personal interfaces.')),
            Q('p3', L('Quale libreria implementa Material in React?', 'Which library implements Material in React?'), ['MUI', 'SwiftUI', 'Bootstrap', 'Qt'], 0, L('Ex Material-UI.', 'Formerly Material-UI.')),
        ], task('text', L('Scrivi tre categorie di stile delle linee guida di Material 3, una per riga con `-`, tra cui il **colore** e la **tipografia**.', 'Write three style categories of the Material 3 guidelines, one per line with `-`, including **colour** and **typography**.'), "- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre categorie', 'Three categories')), re('color|colore|colour', L('Il colore', 'Colour')), re('tipograf|typograph', L('La tipografia', 'Typography'))], '', "- colore\n- tipografia\n- forme"), [
            dMatch(pMatch(), [['Material 3', L('Versione attuale', 'Current version')], ['Material You', L('Colori dallo sfondo', 'Colours from the wallpaper')], ['MUI', 'React'], ['Jetpack Compose', 'Android'], ['m3.material.io', L('Linee guida ufficiali', 'Official guidelines')]], L('L’ecosistema Material.', 'The Material ecosystem.')),
            dFlash(pFlash(), [[L('Material Design è stato creato da Google', 'Material Design was created by Google'), true], [L('Material si usa solo su Android', 'Material is used only on Android'), false], [L('Material 3 ha forme più arrotondate', 'Material 3 has rounder shapes'), true], [L('Material You vieta i colori personalizzati', 'Material You forbids custom colours'), false]], L('Conoscere Material.', 'Knowing Material.')),
        ]),
        lesson('color', L('Ruoli di colore e colore dinamico', 'Colour roles and dynamic colour'), [
            P('M3 non chiede di scegliere singoli colori ma **ruoli**: `primary` (azioni principali), `secondary` e `tertiary` (accenti), `error`, `surface` (sfondi e contenitori) e per ognuno il colore **on** che ci sta sopra (`on-primary`, `on-surface`), più i **container** (`primary-container` e `on-primary-container`) per elementi meno prominenti. Così il contrasto è garantito.', 'M3 does not ask you to pick single colours but **roles**: `primary` (main actions), `secondary` and `tertiary` (accents), `error`, `surface` (backgrounds and containers) and for each the **on** colour that goes on top (`on-primary`, `on-surface`), plus **containers** (`primary-container` and `on-primary-container`) for less prominent elements. That way contrast is guaranteed.'),
            P('Da un solo **colore sorgente** (il brand o lo sfondo dell’utente) l’algoritmo genera **palette tonali** di 13 toni e assegna i ruoli sia per il tema chiaro sia per quello scuro: è il **colore dinamico**. Lo strumento **Material Theme Builder** esporta i token in CSS, Compose o Flutter.', 'From a single **source colour** (the brand or the user’s wallpaper) the algorithm generates 13-tone **tonal palettes** and assigns the roles for both light and dark themes: that is **dynamic colour**. The **Material Theme Builder** tool exports the tokens to CSS, Compose or Flutter.'),
            C(':root {
  --md-sys-color-primary: #6750a4;
  --md-sys-color-on-primary: #ffffff;
  --md-sys-color-primary-container: #eaddff;
  --md-sys-color-on-primary-container: #21005d;
  --md-sys-color-surface: #fef7ff;
}', 'css'),
        ], [
            Q('c1', L('Che cosa indica un colore “on” come on-primary?', 'What does an “on” colour like on-primary mean?'), [L('Il colore di testo e icone sopra primary', 'The colour of text and icons on top of primary'), L('Un colore acceso', 'A colour that is switched on'), L('Il colore dello sfondo', 'The background colour'), L('Un colore disattivato', 'A disabled colour')], 0, L('Contrasto garantito.', 'Guaranteed contrast.')),
            Q('c2', L('Da che cosa nasce il colore dinamico?', 'What does dynamic colour come from?'), [L('Da un colore sorgente', 'From a source colour'), L('Da una foto del designer', 'From a designer’s photo'), L('Da colori casuali', 'From random colours'), L('Da una lista fissa di 5 temi', 'From a fixed list of 5 themes')], 0, L('Palette tonali generate.', 'Generated tonal palettes.')),
            Q('c3', L('A che cosa servono i container come primary-container?', 'What are containers like primary-container for?'), [L('Elementi meno prominenti del primary', 'Elements less prominent than primary'), L('Contenitori Docker', 'Docker containers'), L('I bordi della pagina', 'The page borders'), L('I messaggi di errore', 'Error messages')], 0, L('Tinta più tenue, stesso ruolo.', 'Softer tint, same role.')),
        ], task('css', L('Usa i ruoli di colore nel pulsante `.filled`: `background` con `var(--md-sys-color-primary)` e `color` con `var(--md-sys-color-on-primary)`.', 'Use colour roles in the `.filled` button: `background` with `var(--md-sys-color-primary)` and `color` with `var(--md-sys-color-on-primary)`.'), ":root {\n  --md-sys-color-primary: #6750a4;\n  --md-sys-color-on-primary: #ffffff;\n}\n.filled {\n  border: none;\n  border-radius: 20px;\n}\n", [re('\.filled\s*\{[^}]*background(-color)?\s*:\s*var\(\s*--md-sys-color-primary\s*\)', L('Sfondo primary', 'Primary background')), re('\.filled\s*\{[^}]*(?<!-)color\s*:\s*var\(\s*--md-sys-color-on-primary\s*\)', L('Testo on-primary', 'On-primary text')), css('.filled', 'color', 'rgb(255, 255, 255)', L('Testo bianco', 'White text'))], '<button class="filled">Salva</button>', ".filled {\n  background: var(--md-sys-color-primary);\n  color: var(--md-sys-color-on-primary);\n}"), [
            dMatch(pMatch(), [['primary', L('Azioni principali', 'Main actions')], ['on-primary', L('Testo sopra primary', 'Text on primary')], ['surface', L('Sfondi e contenitori', 'Backgrounds and containers')], ['error', L('Errori', 'Errors')], ['primary-container', L('Elementi meno prominenti', 'Less prominent elements')]], L('I ruoli di colore.', 'Colour roles.')),
            dBlanks(pFill(), ".filled {\n  background: var(--md-sys-color-___);\n  color: var(--md-sys-color-___);\n}", ['primary', 'on-primary'], ['surface', 'error-container'], L('Ogni ruolo con il suo “on”.', 'Each role with its “on”.')),
        ]),
        lesson('components', L('Componenti, tipografia e forme', 'Components, typography and shapes'), [
            P('M3 ha cinque tipi di **pulsanti** in ordine di enfasi: **filled** (azione più importante), **tonal** (filled tonal), **elevated**, **outlined** e **text**. Poi **FAB** (per l’azione principale della schermata, anche **extended** con testo), **navigation bar** in basso (3-5 destinazioni), **navigation rail** su tablet, **top app bar**, **card**, **chip**, **dialog**, **bottom sheet**, **snackbar**, **switch**.', 'M3 has five kinds of **buttons** in order of emphasis: **filled** (most important action), **tonal** (filled tonal), **elevated**, **outlined** and **text**. Then the **FAB** (for the screen’s main action, also **extended** with a label), bottom **navigation bar** (3-5 destinations), **navigation rail** on tablets, **top app bar**, **cards**, **chips**, **dialogs**, **bottom sheets**, **snackbars**, **switches**.'),
            P('La **scala tipografica** ha cinque ruoli, ognuno in tre misure (large, medium, small): **display**, **headline**, **title**, **body**, **label**. Il carattere predefinito è **Roboto** (o il font di sistema). Le **forme** seguono una scala di arrotondamento da none a full (pillola): i pulsanti sono a pillola, le card più squadrate, i dialoghi molto arrotondati.', 'The **type scale** has five roles, each in three sizes (large, medium, small): **display**, **headline**, **title**, **body**, **label**. The default typeface is **Roboto** (or the system font). **Shapes** follow a rounding scale from none to full (pill): buttons are pill-shaped, cards squarer, dialogs very rounded.'),
        ], [
            Q('m1', L('Quale pulsante M3 ha più enfasi?', 'Which M3 button has the most emphasis?'), ['Filled', 'Text', 'Outlined', 'Elevated'], 0, L('Per l’azione più importante.', 'For the most important action.')),
            Q('m2', L('Quanti ruoli ha la scala tipografica M3?', 'How many roles does the M3 type scale have?'), [L('Cinque, ognuno in tre misure', 'Five, each in three sizes'), L('Uno solo', 'Just one'), L('Dieci senza misure', 'Ten without sizes'), L('Due', 'Two')], 0, L('Display, headline, title, body, label.', 'Display, headline, title, body, label.')),
            Q('m3', L('Che cosa usa M3 su tablet invece della navigation bar?', 'What does M3 use on tablets instead of the navigation bar?'), [L('La navigation rail', 'The navigation rail'), L('Un menu a tendina', 'A dropdown menu'), L('Il FAB', 'The FAB'), L('Una snackbar', 'A snackbar')], 0, L('Una colonna laterale stretta.', 'A narrow side column.')),
        ], task('text', L('Ordina i cinque pulsanti M3 dal più al meno enfatico, una riga ciascuno numerata da `1.` a `5.`.', 'Order the five M3 buttons from most to least emphatic, one line each numbered `1.` to `5.`.'), "1. \n2. \n3. \n4. \n5. ", [re('^1\.\s*filled\b(?!\s*tonal)', L('Filled', 'Filled')), re('^2\.\s*(filled\s*)?tonal', L('Tonal', 'Tonal')), re('^3\.\s*elevated', L('Elevated', 'Elevated')), re('^4\.\s*outlined', L('Outlined', 'Outlined')), re('^5\.\s*text', L('Text', 'Text'))], '', "1. filled\n2. tonal\n3. elevated\n4. outlined\n5. text"), [
            dOrder(pSort(), ['Filled', 'Filled tonal', 'Elevated', 'Outlined', 'Text'], L('Dal più al meno enfatico.', 'From most to least emphatic.')),
            dMatch(pMatch(), [['Display', L('Testi grandissimi', 'Huge text')], ['Headline', L('Titoli di sezione', 'Section headings')], ['Body', L('Testo corrente', 'Running text')], ['Label', L('Pulsanti e didascalie', 'Buttons and captions')], ['Navigation rail', 'Tablet']], L('Componenti e testo.', 'Components and text.')),
        ]),
        lesson('layout', L('Layout adattivo, elevazione e movimento', 'Adaptive layout, elevation and motion'), [
            P('M3 divide gli schermi in **classi di larghezza**: **compact** (meno di 600 dp, telefoni), **medium** (600-839, tablet piccoli e telefoni pieghevoli), **expanded** (840 e oltre, tablet e desktop), più large ed extra-large. Il layout si adatta: la navigation bar diventa rail e poi **navigation drawer**, una colonna diventa **lista-dettaglio** a due riquadri.', 'M3 splits screens into **window size classes**: **compact** (under 600 dp, phones), **medium** (600-839, small tablets and foldables), **expanded** (840 and up, tablets and desktop), plus large and extra-large. The layout adapts: the navigation bar becomes a rail and then a **navigation drawer**, one column becomes a two-pane **list-detail**.'),
            P('L’**elevazione** in M3 si esprime soprattutto con il **colore tonale** della superficie (più alta = tinta più carica del primary), con ombre solo dove serve separare. Il **movimento** usa curve **emphasized** per le transizioni importanti e durate brevi; i pattern di transizione (container transform, shared axis, fade through) spiegano le relazioni tra schermate.', '**Elevation** in M3 is expressed mainly through the surface’s **tonal colour** (higher = stronger primary tint), with shadows only where separation is needed. **Motion** uses **emphasized** easing curves for important transitions and short durations; transition patterns (container transform, shared axis, fade through) explain relationships between screens.'),
        ], [
            Q('l1', L('Quale classe di larghezza ha un telefono in verticale?', 'Which width class does a portrait phone have?'), ['Compact', 'Medium', 'Expanded', 'Extra-large'], 0, L('Meno di 600 dp.', 'Under 600 dp.')),
            Q('l2', L('Come mostra l’elevazione M3?', 'How does M3 show elevation?'), [L('Soprattutto con il colore tonale', 'Mainly with tonal colour'), L('Solo con ombre nere', 'Only with black shadows'), L('Con bordi tratteggiati', 'With dashed borders'), L('Non la mostra', 'It does not')], 0, L('Più in alto, più tinta.', 'Higher, more tint.')),
            Q('l3', L('Che cosa diventa la navigation bar su schermi expanded?', 'What does the navigation bar become on expanded screens?'), [L('Una rail o un navigation drawer', 'A rail or a navigation drawer'), L('Un FAB', 'A FAB'), L('Una snackbar', 'A snackbar'), L('Sparisce del tutto', 'It disappears entirely')], 0, L('Layout adattivo.', 'Adaptive layout.')),
        ], task('css', L('Rendi adattiva la `.lista`: dentro una media query `min-width: 840px` (expanded) dagli `display: grid` con `grid-template-columns` a due colonne.', 'Make `.lista` adaptive: inside a `min-width: 840px` media query (expanded) give it `display: grid` with a two-column `grid-template-columns`.'), ".lista {\n  display: block;\n}\n", [re('@media[^{]*min-width\s*:\s*840px[^{]*\{[^@]*\.lista\s*\{[^}]*display\s*:\s*grid', L('Griglia da 840px', 'Grid from 840px')), re('grid-template-columns\s*:\s*(\S+\s+\S+|repeat\(\s*2)', L('Due colonne', 'Two columns'))], '<div class="lista"><section>Elenco</section><section>Dettaglio</section></div>', "@media (min-width: 840px) {\n  .lista {\n    display: grid;\n    grid-template-columns: 1fr 2fr;\n  }\n}"), [
            dMatch(pMatch(), [['Compact', L('Meno di 600 dp', 'Under 600 dp')], ['Medium', '600-839 dp'], ['Expanded', L('840 dp e oltre', '840 dp and up')], ['Navigation drawer', L('Navigazione su schermi grandi', 'Navigation on large screens')], ['Container transform', L('Un elemento si espande in schermata', 'An element expands into a screen')]], L('Adattarsi alle finestre.', 'Adapting to windows.')),
            dFlash(pFlash(), [[L('I telefoni pieghevoli aperti sono spesso medium', 'Open foldables are often medium'), true], [L('In M3 l’elevazione usa solo ombre', 'In M3 elevation uses only shadows'), false], [L('Su schermi grandi si usa spesso la lista-dettaglio', 'Large screens often use list-detail'), true], [L('M3 usa lo stesso layout su tutti gli schermi', 'M3 uses the same layout on every screen'), false]], L('Material adattivo.', 'Adaptive Material.')),
        ]),
        lesson('code', L('Material 3 nel codice', 'Material 3 in code'), [
            P('Il **Material Theme Builder** parte da un colore sorgente (o da un’immagine) e genera l’intera palette: ruoli chiari e scuri come `primary`, `on-primary`, `surface`, `outline`. Si esporta come token per il web (variabili CSS), per Android (Compose) e per Flutter.', 'The **Material Theme Builder** starts from a source colour (or an image) and generates the whole palette: light and dark roles such as `primary`, `on-primary`, `surface`, `outline`. It exports as tokens for the web (CSS variables), Android (Compose) and Flutter.'),
            C(':root {
  --md-sys-color-primary: #6750A4;
  --md-sys-color-on-primary: #FFFFFF;
  --md-sys-color-surface: #FEF7FF;
}
.btn-filled {
  background: var(--md-sys-color-primary);
  color: var(--md-sys-color-on-primary);
  border-radius: 20px;
}', 'css'),
            P('In **Jetpack Compose** il tema si applica con `MaterialTheme(colorScheme = …)`, e su Android 12+ `dynamicLightColorScheme(context)` prende i colori dallo sfondo dell’utente. In **Flutter** basta `ThemeData(colorSchemeSeed: …, useMaterial3: true)`.', 'In **Jetpack Compose** the theme is applied with `MaterialTheme(colorScheme = …)`, and on Android 12+ `dynamicLightColorScheme(context)` takes colours from the user’s wallpaper. In **Flutter** `ThemeData(colorSchemeSeed: …, useMaterial3: true)` is enough.'),
        ], [
            Q('mc1', L('Da che cosa parte il Theme Builder?', 'What does the Theme Builder start from?'), [L('Un colore sorgente o un’immagine', 'A source colour or an image'), L('Un font', 'A font'), L('Un logo vettoriale soltanto', 'Only a vector logo'), L('Un file CSS esistente', 'An existing CSS file')], 0, L('Genera tutti i ruoli.', 'It generates every role.')),
            Q('mc2', L('Quale colore va sul testo di un pulsante `primary`?', 'Which colour goes on a `primary` button’s text?'), ['on-primary', 'primary', 'surface', 'outline'], 0, L('“on” = sopra a.', '“on” = on top of.')),
            Q('mc3', L('Come attivi Material 3 in Flutter con un colore seme?', 'How do you enable Material 3 in Flutter with a seed colour?'), [L('`ThemeData(colorSchemeSeed: …, useMaterial3: true)`', '`ThemeData(colorSchemeSeed: …, useMaterial3: true)`'), L('`MaterialApp(color: …)`', '`MaterialApp(color: …)`'), L('`Theme.of(context)`', '`Theme.of(context)`'), L('Non si può', 'You cannot')], 0, L('Il resto lo genera Flutter.', 'Flutter generates the rest.')),
        ], task('css', L('Dai a `.btn` lo sfondo `var(--md-sys-color-primary)` e il colore del testo `var(--md-sys-color-on-primary)`.', 'Give `.btn` the background `var(--md-sys-color-primary)` and text colour `var(--md-sys-color-on-primary)`.'), ':root {
  --md-sys-color-primary: #6750A4;
  --md-sys-color-on-primary: #FFFFFF;
}', [css('.btn', 'background-color', 'rgb(103, 80, 164)', L('Lo sfondo è primary', 'The background is primary')), css('.btn', 'color', 'rgb(255, 255, 255)', L('Il testo è on-primary', 'The text is on-primary'))], '<button class="btn">Salva</button>', ":root {\n  --md-sys-color-primary: #6750A4;\n  --md-sys-color-on-primary: #FFFFFF;\n}\n.btn {\n  background: var(--md-sys-color-primary);\n  color: var(--md-sys-color-on-primary);\n}"), [
            dMatch(pMatch(), [['primary', L('Colore principale', 'Main colour')], ['on-primary', L('Testo sopra primary', 'Text on primary')], ['surface', L('Sfondo delle superfici', 'Surface background')], ['dynamicLightColorScheme', L('Colori dallo sfondo', 'Colours from the wallpaper')], ['colorSchemeSeed', L('Colore seme in Flutter', 'Seed colour in Flutter')]], L('Material nel codice.', 'Material in code.')),
            dFlash(pFlash(), [[L('Il Theme Builder esporta variabili CSS', 'The Theme Builder exports CSS variables'), true], [L('Il colore dinamico funziona su ogni versione di Android', 'Dynamic colour works on every Android version'), false], [L('on-surface va sul testo sopra surface', 'on-surface goes on text over surface'), true], [L('Material 3 richiede di scegliere ogni colore a mano', 'Material 3 requires picking every colour by hand'), false]], L('Dal seme alla palette.', 'From seed to palette.')),
        ]),
